int main(){GuestMemory64 m;using F=GuestMemory64::Fault;assert(m.map(0x1000,4096,7)==F::none);Cpu64State init;auto run=[&](auto code,uint64_t v){init.gpr[7]=v;assert(m.write(0x1000,code)==F::none);auto s=executeGuest64(m,0x1000,1,0x1900,nullptr,0,0,0,0,&init);assert(s.steps==1);return s;};auto l=std::array<uint8_t,5>{0xf3,0x48,0x0f,0xbd,0xc7};assert(run(l,16).gpr[0]==59);assert(run(l,0).gpr[0]==64&&run(l,0).cf);assert(run(l,1ull<<63).zf);assert(run(std::array<uint8_t,5>{0xf3,0x48,0x0f,0xbc,0xc7},16).gpr[0]==4);assert(run(std::array<uint8_t,4>{0x48,0x0f,0xbd,0xc7},16).gpr[0]==4);assert(run(std::array<uint8_t,4>{0x48,0x0f,0xbc,0xc7},16).gpr[0]==4);assert(run(std::array<uint8_t,5>{0xf3,0x48,0x0f,0xb8,0xc7},15).gpr[0]==4);ScarlettImports64 i;assert(i.install(m));uint64_t r=0;auto call=[&](const char*d,const char*n,uint64_t a=0,uint64_t b=0,uint64_t c=0){auto p=i.registerImport(d,n);assert(p&&i.dispatch(p,m,a,r,b,c));return r;};assert(call("MSVCP140.dll","_Query_perf_frequency")==1000000000);assert(call("MSVCP140.dll","_Query_perf_counter")>0);assert(call("MSVCP140.dll","_Xtime_get_ticks")>0);assert(call("api-ms-win-crt-time-l1-1-0.dll","_time64",0x1100)>0);call("api-ms-win-core-synch-l1-1-0.dll","AcquireSRWLockExclusive",0x1200);call("api-ms-win-core-synch-l1-1-0.dll","ReleaseSRWLockExclusive",0x1200);assert(call("api-ms-win-core-com-l1-1-0.dll","StringFromGUID2",0x1200,0x1300,39)==39);assert(call("api-ms-win-core-file-l1-1-0.dll","FileTimeToLocalFileTime",0x1100,0x1400)==1);assert(call("api-ms-win-core-file-l1-1-0.dll","LocalFileTimeToFileTime",0x1400,0x1500)==1);std::cout<<"V38 tests passed\n";}
